package com.leetcode.backend.controller;
import com.leetcode.backend.model.*; import com.leetcode.backend.repository.*; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/problems/{problemId}/editorial") public class EditorialController { private final EditorialRepository editorials; private final ProblemRepository problems; public EditorialController(EditorialRepository e,ProblemRepository p){editorials=e;problems=p;}
 @GetMapping public Editorial get(@PathVariable Long problemId){return editorials.findByProblemId(problemId).orElseThrow(()->new RuntimeException("Editorial not found."));}
 @PutMapping public Editorial put(@PathVariable Long problemId,@RequestBody Editorial body,Authentication a){if(a.getAuthorities().stream().noneMatch(x->x.getAuthority().equals("ROLE_ADMIN")))throw new org.springframework.security.access.AccessDeniedException("Admin required."); Editorial value=editorials.findByProblemId(problemId).orElseGet(Editorial::new); value.setProblem(problems.findById(problemId).orElseThrow(()->new RuntimeException("Problem not found."))); value.setIntuition(body.getIntuition());value.setApproach(body.getApproach());value.setAlgorithmExplanation(body.getAlgorithmExplanation());value.setEdgeCases(body.getEdgeCases());value.setTimeComplexity(body.getTimeComplexity());value.setSpaceComplexity(body.getSpaceComplexity());value.setJavaSolution(body.getJavaSolution());value.setCppSolution(body.getCppSolution());value.setPythonSolution(body.getPythonSolution());return editorials.save(value);}}
